import { atom, read, update } from 'claude-code'
import type { EngineInterface as Engine, Register } from 'claude-code'

import type { Check, Grade } from '../types'

const grade = atom({ plugin: 'jev-prompt-grader', key: 'grade' } as const, null)
const hasDraft = atom({ plugin: 'jev-prompt-grader', key: 'hasDraft' } as const, false)
const isStale = atom({ plugin: 'jev-prompt-grader', key: 'isStale' } as const, false)
const isGrading = atom({ plugin: 'jev-prompt-grader', key: 'isGrading' } as const, false)
const history = atom({ plugin: 'jev-prompt-grader', key: 'history' } as const, [] as string[])

const ENDPOINT = 'https://api.typesafe.ai/v1/systemone'
const LEVELS = ['poor', 'weak', 'okay', 'good', 'great']
// Earlier prompts sent along as context, and how much of each.
const HISTORY_SIZE = 3
const HISTORY_CHARS = 2000

// The kinds of request Jev picks from in the first call; each check lists the kinds it fits.
const KINDS = {
  'bug fix': 'fix broken behaviour',
  feature: 'build something new or extend existing behaviour',
  refactor: 'restructure existing code without changing behaviour',
  question: 'explain or answer something, no code change asked',
  explore: 'brainstorm, research, investigate or plan',
  other: 'anything else',
} as const
type Kind = keyof typeof KINDS

const CODE_CHANGE: Kind[] = ['bug fix', 'feature', 'refactor']
const ALL = Object.keys(KINDS) as Kind[]

// Yes/no checks Jev answers with a probability, asked only for the kinds they fit.
// Label is what we show when it fails.
const CHECKS: { id: string; label: string; instructions: string; kinds: Kind[] }[] = [
  {
    id: 'goal',
    label: 'no clear goal',
    instructions: 'Does the prompt state a clear goal or desired outcome?',
    kinds: ALL,
  },
  {
    id: 'context',
    label: 'too little context',
    instructions:
      'Does the prompt give enough context (relevant files, background, current behaviour) to act without guessing?',
    kinds: ALL,
  },
  {
    id: 'scope',
    label: 'vague scope',
    instructions:
      'Is the scope specific (what to change and where) rather than vague or open-ended?',
    kinds: CODE_CHANGE,
  },
  {
    id: 'done',
    label: 'no success criteria',
    instructions:
      'Does the prompt say how to tell the task is done (expected result, tests to pass, acceptance criteria)?',
    kinds: CODE_CHANGE,
  },
  {
    id: 'focus',
    label: 'mixes several tasks',
    instructions: 'Is the prompt focused on a single task rather than several unrelated asks?',
    kinds: ALL,
  },
  {
    id: 'references',
    label: 'no concrete pointers',
    instructions:
      'Does the prompt point to concrete places to look (file names, functions, components, URLs, commands)?',
    kinds: CODE_CHANGE,
  },
  {
    id: 'repro',
    label: 'no error or repro steps',
    instructions: 'Does the prompt include the error message, logs or steps to reproduce the bug?',
    kinds: ['bug fix'],
  },
  {
    id: 'constraints',
    label: 'no constraints',
    instructions:
      'Does the prompt state constraints where they matter (what must not change, libraries or patterns to use or avoid, compatibility, style)? Answer yes if the task is simple enough to need none.',
    kinds: ['feature', 'refactor'],
  },
  {
    id: 'why',
    label: 'missing the why',
    instructions:
      'Does the prompt explain why the change is wanted or what problem it solves, so trade-offs can be judged? Answer yes if the reason is obvious from the request.',
    kinds: ['feature', 'refactor'],
  },
  {
    id: 'specific',
    label: 'question too broad',
    instructions:
      'Does the prompt ask a specific question rather than about a broad topic?',
    kinds: ['question', 'explore'],
  },
  {
    id: 'format',
    label: 'no answer format',
    instructions:
      'Does the prompt say what kind of answer is wanted (a short answer, an explanation, a comparison, a recommendation, a plan, a code example)? Answer yes if it is obvious from the question.',
    kinds: ['question', 'explore'],
  },
  {
    id: 'clear',
    label: 'ambiguous wording',
    instructions:
      'Is the wording unambiguous, with no unclear references such as "it", "this" or "that thing" whose meaning cannot be told from the prompt alone?',
    kinds: ALL,
  },
]

// Failed checks shown in the band; the rest are summed up as "+N more".
const MAX_SHOWN = 4

type JevAnswer = { noul?: number; score?: number; choice?: string }
type JevResponse = { answers?: Record<string, JevAnswer> }

// Every question grades the last prompt only; earlier ones are there to resolve follow-ups.
const CONTEXT_NOTE =
  ' Judge only the prompt under "Prompt to grade". Earlier prompts are context: a follow-up that is clear given them counts as clear.'

// What Jev reads: the draft alone, or the draft after the earlier prompts.
function buildState(draft: string, earlier: readonly string[]) {
  if (earlier.length === 0) {
    return draft
  }
  const lines = earlier.map((t, i) => `${i + 1}. ${t.slice(0, HISTORY_CHARS)}`)
  return `Earlier prompts in this conversation, oldest first:\n${lines.join('\n')}\n\nPrompt to grade:\n${draft}`
}

function checksFor(kind: Kind) {
  return CHECKS.filter(c => c.kinds.includes(kind))
}

// First call: what kind of request this is.
function kindQuestion(note: string) {
  return {
    kind: { type: 'choice', instructions: 'What kind of request is this?' + note, criteria: KINDS },
  }
}

// Second call: the overall score and the checks that fit the kind.
function gradeQuestions(kind: Kind, note: string) {
  const questions: Record<string, unknown> = {
    overall: {
      type: 'score',
      instructions:
        `This is a ${kind} request (${KINDS[kind]}). How good is the prompt for an AI coding assistant to act on without follow-up questions?` +
        note,
      criteria: [
        'Poor: unclear what is wanted',
        'Weak: rough idea, major gaps',
        'Okay: workable but the assistant must guess',
        'Good: clear, minor gaps',
        `Great: everything a ${kind} request needs`,
      ],
    },
  }
  for (const c of checksFor(kind)) {
    questions[c.id] = { type: 'noul', instructions: c.instructions + note }
  }
  return questions
}

function toGrade(answers: Record<string, JevAnswer>, kind: Kind): Grade {
  const score = answers.overall?.score ?? 0
  const level = Math.max(0, Math.min(LEVELS.length - 1, Math.round(score)))
  const missing: Check[] = checksFor(kind)
    .map(c => ({ id: c.id, label: c.label, p: answers[c.id]?.noul ?? 1 }))
    .filter(c => c.p < 0.5)
    .sort((a, b) => a.p - b.p)
  return { status: 'done', level, label: LEVELS[level] ?? 'okay', kind, missing }
}

// One Jev call: the answers, or the error to show.
async function askJev(
  $: Engine,
  apiKey: string,
  state: string,
  questions: Record<string, unknown>,
): Promise<{ answers: Record<string, JevAnswer> } | { error: string }> {
  try {
    const res = await $.http.fetch(ENDPOINT, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ model: 'jev-latest', state, questions }),
    })
    if (!res.ok) {
      return { error: `Jev returned HTTP ${res.status}` }
    }
    return { answers: (JSON.parse(res.text) as JevResponse).answers ?? {} }
  } catch {
    return { error: 'Could not reach Jev' }
  }
}

// Counts requests so a slow answer for an older draft never overwrites a newer one.
let latest = 0
// The draft the shown grade belongs to, so cursor moves and no-op edits do not mark it stale.
let lastGraded = ''

// Sends the draft to Jev in two calls: first the kind of request, then the checks that fit
// it. Only ever called from the Grade button, so nothing leaves the machine unless the
// person asks for it.
async function gradeDraft($: Engine) {
  const draft = (await $.prompt.read()).text.trim()
  if (!draft) {
    return
  }
  lastGraded = draft

  const apiKey = await $.env.get('TYPESAFE_API_KEY')
  if (!apiKey) {
    await update($, grade, (): Grade => ({
      status: 'error',
      message: 'Set TYPESAFE_API_KEY to grade prompts',
    }))
    return
  }

  const id = ++latest
  await update($, isGrading, () => true)
  const earlier = await read($, history)
  const state = buildState(draft, earlier)
  const note = earlier.length > 0 ? CONTEXT_NOTE : ''

  let result: Grade
  const first = await askJev($, apiKey, state, kindQuestion(note))
  if ('error' in first) {
    result = { status: 'error', message: first.error }
  } else {
    const choice = first.answers.kind?.choice
    const kind: Kind = choice && choice in KINDS ? (choice as Kind) : 'other'
    // Skip the second call when a newer request has already taken over.
    if (id !== latest) {
      return
    }
    const second = await askJev($, apiKey, state, gradeQuestions(kind, note))
    result =
      'error' in second
        ? { status: 'error', message: second.error }
        : toGrade(second.answers, kind)
  }

  if (id === latest) {
    await update($, grade, () => result)
    await update($, isGrading, () => false)
    await update($, isStale, () => false)
  }
}

async function reset($: Engine) {
  latest += 1
  lastGraded = ''
  await update($, grade, () => null)
  await update($, hasDraft, () => false)
  await update($, isStale, () => false)
  await update($, isGrading, () => false)
}

export const register: Register = on => {
  // Tracks the draft locally (nothing is sent) so the band knows when to show and when a grade is stale.
  on('prompt.edit', async ($, e, next) => {
    const box = await next(e)
    const draft = box.text.trim()

    if (!draft) {
      await reset($)
      return box
    }
    if (!(await read($, hasDraft))) {
      await update($, hasDraft, () => true)
    }
    // Stale exactly when a grade is shown for text other than what is in the box now.
    const stale = (await read($, grade)) !== null && draft !== lastGraded
    if ((await read($, isStale)) !== stale) {
      await update($, isStale, () => stale)
    }
    return box
  })

  // Sending the prompt empties the box, so the grade goes with it. The prompt is kept,
  // in this session only, as context for grading the next ones.
  on('prompt.submit', async ($, e, next) => {
    const result = await next(e)
    if (e.origin.kind === 'composer') {
      await reset($)
      const text = e.text.trim()
      if (text && !text.startsWith('/')) {
        await update($, history, h => [...h, text].slice(-HISTORY_SIZE))
      }
    }
    return result
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const g = await read($, grade)
    const has = await read($, hasDraft)
    if (e.props.hasSurvey || !has) {
      return next(e)
    }

    const { Box, Button, Text } = $.ui.resolve(e)
    const grading = await read($, isGrading)
    const stale = await read($, isStale)
    const gradeButton = grading ? null : (
      <Button
        key="grade"
        label={g?.status === 'done' ? 'Re-grade' : 'Grade prompt'}
        onPress={() => gradeDraft($)}
      />
    )

    if (g === null) {
      return (
        <Box>
          {grading ? <Text dimColor>Jev is grading your prompt…</Text> : gradeButton}
        </Box>
      )
    }

    if (g.status === 'error') {
      return (
        <Box>
          <Text dimColor>Prompt grader: {g.message} </Text>
          {gradeButton}
        </Box>
      )
    }

    const color = g.level >= 3 ? 'green' : g.level === 2 ? 'yellow' : 'red'
    const dots = '●'.repeat(g.level + 1) + '○'.repeat(LEVELS.length - g.level - 1)
    const shown = g.missing.slice(0, MAX_SHOWN).map(m => `${m.label} (${Math.round(m.p * 100)}%)`)
    const more = g.missing.length - shown.length
    const notes = g.missing.length
      ? shown.join(' · ') + (more > 0 ? ` · +${more} more` : '')
      : 'nothing missing'
    const status = grading ? ' · grading…' : stale ? ' · edited since ' : ''

    return (
      <Box>
        <Text color={stale || grading ? undefined : color} dimColor={stale || grading}>
          {dots} {g.label}
        </Text>
        <Text dimColor>
          {' '}
          [{g.kind}] {notes}
          {status}
        </Text>
        {stale ? gradeButton : null}
      </Box>
    )
  })
}

