export type Check = { id: string; label: string; p: number }

export type Grade =
  | { status: 'error'; message: string }
  | {
      status: 'done'
      level: number // 0..4, rounded expected score
      label: string
      kind: string
      missing: Check[] // checks with p < 0.5, worst first
    }

declare module 'claude-code' {
  interface PluginState {
    'jev-prompt-grader': {
      grade: Grade | null // the last result, kept on screen while a new one loads
      hasDraft: boolean // the prompt box holds text
      isStale: boolean // the draft changed since it was graded
      isGrading: boolean // a Jev request is in flight
      history: string[] // the person's last sent prompts, oldest first, sent along as context
    }
  }
}
